package com.careerpilot.backend.modules.discovery.adapters.in.web;
import com.careerpilot.backend.modules.discovery.domain.*; import com.careerpilot.backend.modules.discovery.services.*; import com.careerpilot.connector.sdk.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/discovery") public class DiscoveryController {private final JobDiscoveryService jobs;private final ConnectorRegistry registry;private final DiscoveryScheduler scheduler;public DiscoveryController(JobDiscoveryService j,ConnectorRegistry r,DiscoveryScheduler s){jobs=j;registry=r;scheduler=s;}@GetMapping("/jobs")public List<DiscoveryJob> jobs(){return jobs.jobs();}@GetMapping("/jobs/{id}")public DiscoveryJob job(@PathVariable UUID id){return jobs.job(id);}@GetMapping("/connectors/health")public List<ConnectorHealth> health(){return registry.health();}@org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')")@PostMapping("/synchronize")public List<SynchronizationResult> sync(){return scheduler.triggerAll();}}
